    name = "Subset Sum"

    @classmethod
    def validate(cls, instance: object) -> None:
        require_keys(instance, {"numbers", "target"})
        assert isinstance(instance, dict)
        validate_numbers(instance["numbers"])
        require_int(instance["target"], "target")

